function readNestedString(
  source: unknown,
  keys: string[],
  fallback = "—"
): string {
  if (!source || typeof source !== "object") return fallback;

  const row = source as Record<string, unknown>;

  for (const key of keys) {
    const value = row[key];

    if (typeof value === "string" && value.trim()) return value;
    if (typeof value === "number") return String(value);

    if (value && typeof value === "object" && !Array.isArray(value)) {
      const nested = value as Record<string, unknown>;

      for (const nestedKey of [
        "name",
        "company_name",
        "customer_name",
        "label",
        "title",
      ]) {
        const nestedValue = nested[nestedKey];

        if (typeof nestedValue === "string" && nestedValue.trim()) {
          return nestedValue;
        }
      }
    }
  }

  return fallback;
}

function badgeStyle(kind: string) {
  const map: Record<string, { bg: string; color: string }> = {
    "Sesuai Target": { bg: "#eef2f6", color: "#64748b" },
    Gangguan: { bg: "#fee2e2", color: "#dc2626" },
    "At Risk": { bg: "#fee2e2", color: "#dc2626" },
    "On Time": { bg: "#dcfce7", color: "#16a34a" },
    Missed: { bg: "#fee2e2", color: "#dc2626" },
    Critical: { bg: "#fee2e2", color: "#dc2626" },
    High: { bg: "#fef3c7", color: "#d99200" },
    Medium: { bg: "#e0f2fe", color: "#0369a1" },
  };

  const config = map[kind] ?? { bg: "#f1f5f9", color: "#64748b" };

  return {
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    padding: "3px 9px",
    borderRadius: 999,
    background: config.bg,
    color: config.color,
    fontSize: "0.65rem",
    lineHeight: 1.2,
    fontWeight: 700,
    whiteSpace: "nowrap",
  } as const;
}

