function KpiCard({
  label,
  value,
  note,
  noteColor = BRAND.slate,
  icon,
  iconColor,
  iconBackground,
}: {
  label: string;
  value: string | number;
  note?: string;
  noteColor?: string;
  icon: ReactNode;
  iconColor: string;
  iconBackground: string;
}) {
  return (
    <article className="crm-sla-kpi" tabIndex={0} role="group" aria-label={`${label}: ${value}`}>
      <div className="crm-sla-kpi__top">
        <span className="crm-sla-kpi__icon" style={{ color: iconColor, background: iconBackground }} aria-hidden="true">{icon}</span>
        <span className="crm-sla-kpi__label">{label}</span>
      </div>
      <div>
        <div className="crm-sla-kpi__value">{value}</div>
        {note && <div className="crm-sla-kpi__note" style={{ color: noteColor }}>{note}</div>}
      </div>
    </article>
  );
}

