  async function exportPdf() {
    setShowExportModal(false);

    const exportedAt = new Date();
    const doc = new jsPDF({
      orientation: "landscape",
      unit: "mm",
      format: "a4",
    });

    const W = doc.internal.pageSize.getWidth();
    const H = doc.internal.pageSize.getHeight();

    const drawHeader = () => {
      // Kop surat formal khusus PDF Monitoring SLA.
      doc.setFillColor(255, 255, 255);
      doc.rect(0, 0, W, 40, "F");
      doc.addImage(MSDC_EXPORT_LOGO, "PNG", 10, 5, 36, 20);
      doc.setTextColor(9, 39, 71);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(13);
      doc.text("MSDC SURABAYA", W - 10, 12, { align: "right" });
      doc.setFont("helvetica", "normal");
      doc.setFontSize(8);
      doc.text("CRM & SALES | LAPORAN MONITORING SLA", W - 10, 18, { align: "right" });
      doc.setDrawColor(9, 39, 71);
      doc.setLineWidth(0.7);
      doc.line(10, 29, W - 10, 29);
      doc.setDrawColor(247, 171, 0);
      doc.setLineWidth(0.5);
      doc.line(10, 30.2, W - 10, 30.2);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(10);
      doc.text("Kontrak & SLA - Monitoring SLA", 10, 37);
      doc.setFont("helvetica", "normal");
      doc.setTextColor(BRAND.slate);
      doc.setFontSize(7.5);
      doc.text("MSDC Surabaya | JTV", 10, 43);
      doc.text(`Diekspor: ${exportDateText(exportedAt)}`, W - 10, 43, {
        align: "right",
      });
    };

    drawHeader();

    let y = 50;
    const gap = 2;
    const cardW = (W - 20 - gap * 5) / 6;

    slaKpis.forEach((kpi, index) => {
      const x = 10 + index * (cardW + gap);

      doc.setFillColor(248, 250, 252);
      doc.setDrawColor(229, 231, 235);
      doc.roundedRect(x, y, cardW, 18, 2, 2, "FD");

      doc.setTextColor(BRAND.slate);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(5.7);
      doc.text(kpi.label, x + 2.5, y + 5);

      doc.setTextColor(BRAND.navyText);
      doc.setFontSize(10);
      doc.text(String(kpi.value), x + 2.5, y + 11);

      doc.setTextColor(kpi.noteColor);
      doc.setFont("helvetica", "normal");
      doc.setFontSize(5.3);
      doc.text(kpi.note, x + 2.5, y + 15.5, {
        maxWidth: cardW - 5,
      });
    });

    y += 25;

    doc.setTextColor(BRAND.navyText);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.text("Status SLA Pelanggan", 10, y);
    y += 3;

    autoTable(doc, {
      startY: y,
      head: [[
        "Pelanggan",
        "Kontrak",
        "SLA Level",
        "Target Ketersediaan",
        "Waktu Respon",
        "Waktu Penyelesaian",
        "Status",
      ]],
      body: filteredSlaRows.map(row => [
        row.customer,
        row.contractNumber,
        row.level,
        row.availabilityTarget,
        row.responseTime,
        row.resolutionTime,
        row.status,
      ]),
      theme: "grid",
      margin: { left: 10, right: 10, top: 50, bottom: 12 },
      styles: {
        font: "helvetica",
        fontSize: 6.6,
        cellPadding: 1.8,
        textColor: BRAND.navyText,
        lineColor: BRAND.border,
        lineWidth: 0.15,
      },
      headStyles: {
        fillColor: BRAND.navy,
        textColor: "#FFFFFF",
        fontStyle: "bold",
      },
      alternateRowStyles: {
        fillColor: BRAND.light,
      },
    });

    const afterSla =
      (doc as jsPDF & { lastAutoTable?: { finalY: number } }).lastAutoTable
        ?.finalY ?? y + 30;

    let ticketY = afterSla + 8;

    doc.setTextColor(BRAND.navyText);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.text("SLA Monitoring / Ticket Countdown", 10, ticketY);
    ticketY += 3;

    autoTable(doc, {
      startY: ticketY,
      head: [[
        "Ticket",
        "Customer",
        "Priority",
        "Created",
        "Response Due",
        "Resolution Due",
        "Remaining Time",
        "Status",
      ]],
      body: TICKETS.map(ticket => [
        ticket.ticket,
        ticket.customer,
        ticket.priority,
        ticket.created,
        ticket.responseDue,
        ticket.resolutionDue,
        ticket.remaining,
        ticket.status,
      ]),
      theme: "grid",
      margin: { left: 10, right: 10, top: 50, bottom: 12 },
      styles: {
        font: "helvetica",
        fontSize: 6.2,
        cellPadding: 1.7,
        textColor: BRAND.navyText,
        lineColor: BRAND.border,
        lineWidth: 0.15,
      },
      headStyles: {
        fillColor: BRAND.navy,
        textColor: "#FFFFFF",
        fontStyle: "bold",
      },
      alternateRowStyles: {
        fillColor: BRAND.light,
      },
    });

    const afterTicket =
      (doc as jsPDF & { lastAutoTable?: { finalY: number } }).lastAutoTable
        ?.finalY ?? ticketY + 30;

    if (afterTicket + 45 > H - 12) {
      doc.addPage();
      drawHeader();
      y = 52;
    } else {
      y = afterTicket + 8;
    }

    doc.setTextColor(BRAND.navyText);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.text("Riwayat Eskalasi", 10, y);
    y += 5;

    ESCALATION_STEPS.forEach((step, index) => {
      const x = 10 + index * 66;
      doc.setFillColor(248, 250, 252);
      doc.setDrawColor(229, 231, 235);
      doc.roundedRect(x, y, 60, 17, 2, 2, "FD");
      doc.setTextColor(BRAND.navyText);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(7);
      doc.text(step.role, x + 3, y + 5);
      doc.setFont("helvetica", "normal");
      doc.setTextColor(BRAND.slate);
      doc.setFontSize(6);
      doc.text(step.status, x + 3, y + 10);
      doc.text(step.time, x + 3, y + 14);
    });

    y += 25;

    doc.setTextColor(BRAND.navyText);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.text("Pelanggaran SLA & Service Credit", 10, y);
    y += 4;

    autoTable(doc, {
      startY: y,
      head: [["Downtime", "Target Availability", "Actual Availability", "Status", "Service Credit"]],
      body: [["54 menit", "99.5%", "99.42%", "Miss", "5% dari biaya bulanan"]],
      theme: "grid",
      margin: { left: 10, right: 10 },
      styles: {
        fontSize: 6.6,
        cellPadding: 2,
        textColor: BRAND.navyText,
        lineColor: BRAND.border,
        lineWidth: 0.15,
      },
      headStyles: {
        fillColor: BRAND.navy,
        textColor: "#FFFFFF",
        fontStyle: "bold",
      },
    });

    const pages = doc.getNumberOfPages();
    for (let page = 1; page <= pages; page += 1) {
      doc.setPage(page);
      doc.setTextColor(BRAND.slate);
      doc.setFontSize(7);
      doc.text(`Halaman ${page} / ${pages}`, W - 10, H - 5, {
        align: "right",
      });
    }

    doc.save(
      `msdc-sla-monitoring-${exportedAt.toISOString().slice(0, 10)}.pdf`
    );
  }

  async function exportExcel() {
    setShowExportModal(false);

    const exportedAt = new Date();
    const workbook = new ExcelJS.Workbook();

    workbook.creator = "MSDC Surabaya - JTV";
    workbook.company = "JTV Surabaya";
    workbook.created = exportedAt;

    const ws = workbook.addWorksheet("SLA Monitoring", {
      views: [{ showGridLines: false }],
      pageSetup: {
        orientation: "landscape",
        fitToPage: true,
        fitToWidth: 1,
        fitToHeight: 0,
      },
    });

    const totalColumns = 8;

    for (let column = 1; column <= totalColumns; column += 1) {
      ws.getColumn(column).width = 18;
    }

    for (let row = 1; row <= 4; row += 1) {
      for (let column = 1; column <= totalColumns; column += 1) {
        ws.getCell(row, column).fill = {
          type: "pattern",
          pattern: "solid",
          fgColor: { argb: "FF092747" },
        };
      }
    }

    const msdcImage = workbook.addImage({
      base64: MSDC_EXPORT_LOGO,
      extension: "png",
    });

    const jtvImage = workbook.addImage({
      base64: JTV_EXPORT_LOGO,
      extension: "png",
    });

    ws.addImage(msdcImage, {
      tl: { col: 0.1, row: 0.05 },
      ext: { width: 150, height: 82 },
    });

    ws.addImage(jtvImage, {
      tl: { col: 7.0, row: 0.2 },
      ext: { width: 60, height: 53 },
    });

    ws.mergeCells("C2:F2");
    ws.getCell("C2").value = "Kontrak & SLA - Monitoring SLA";
    ws.getCell("C2").font = {
      name: "Aptos Display",
      size: 18,
      bold: true,
      color: { argb: "FFFFFFFF" },
    };
    ws.getCell("C2").alignment = {
      horizontal: "center",
      vertical: "middle",
    };

    ws.mergeCells("C3:F3");
    ws.getCell("C3").value =
      "Monitoring kepatuhan SLA, ticket countdown, eskalasi, dan service credit";
    ws.getCell("C3").font = {
      size: 9,
      color: { argb: "FFD2DEEA" },
    };
    ws.getCell("C3").alignment = { horizontal: "center" };

    for (let column = 1; column <= totalColumns; column += 1) {
      ws.getCell(5, column).fill = {
        type: "pattern",
        pattern: "solid",
        fgColor: { argb: "FFF7AB00" },
      };
    }
    ws.getRow(5).height = 5;

    ws.mergeCells("A6:D6");
    ws.getCell("A6").value = "MSDC Surabaya | JTV";

    ws.mergeCells("E6:H6");
    ws.getCell("E6").value = `Diekspor: ${exportDateText(exportedAt)}`;
    ws.getCell("E6").alignment = { horizontal: "right" };

    let row = 8;

    // KPI: 6 cards, masing-masing memakai lebar yang nyaman.
    const kpiPairs = [
      [slaKpis[0], slaKpis[1], slaKpis[2]],
      [slaKpis[3], slaKpis[4], slaKpis[5]],
    ];

    kpiPairs.forEach(group => {
      group.forEach((kpi, index) => {
        const startColumn = 1 + index * 2;
        const endColumn = startColumn + 1;

        ws.mergeCells(row, startColumn, row, endColumn);
        ws.mergeCells(row + 1, startColumn, row + 1, endColumn);

        ws.getCell(row, startColumn).value = kpi.label;
        ws.getCell(row + 1, startColumn).value = kpi.value;

        ws.getCell(row, startColumn).font = {
          size: 8,
          bold: true,
          color: { argb: "FF64748B" },
        };
        ws.getCell(row + 1, startColumn).font = {
          size: 14,
          bold: true,
          color: { argb: "FF16213D" },
        };

        for (let rr = row; rr <= row + 1; rr += 1) {
          for (let cc = startColumn; cc <= endColumn; cc += 1) {
            ws.getCell(rr, cc).fill = {
              type: "pattern",
              pattern: "solid",
              fgColor: { argb: "FFF8FAFC" },
            };
            ws.getCell(rr, cc).border = {
              top: { style: "thin", color: { argb: "FFE5E7EB" } },
              bottom: { style: "thin", color: { argb: "FFE5E7EB" } },
              left: { style: "thin", color: { argb: "FFE5E7EB" } },
              right: { style: "thin", color: { argb: "FFE5E7EB" } },
            };
          }
        }
      });

      row += 3;
    });

    row += 1;

    const writeSectionTitle = (title: string) => {
      ws.mergeCells(row, 1, row, 8);
      const cell = ws.getCell(row, 1);
      cell.value = title;
      cell.font = {
        size: 11,
        bold: true,
        color: { argb: "FF16213D" },
      };
      row += 1;
    };

    const writeTable = (
      headers: string[],
      rows: Array<Array<string | number>>
    ) => {
      headers.forEach((header, index) => {
        const cell = ws.getCell(row, index + 1);
        cell.value = header;
        cell.fill = {
          type: "pattern",
          pattern: "solid",
          fgColor: { argb: "FF092747" },
        };
        cell.font = {
          bold: true,
          size: 8,
          color: { argb: "FFFFFFFF" },
        };
        cell.alignment = {
          vertical: "middle",
          wrapText: true,
        };
      });

      row += 1;

      rows.forEach((values, rowIndex) => {
        values.forEach((value, index) => {
          const cell = ws.getCell(row, index + 1);
          cell.value = value;
          cell.font = {
            size: 8,
            color: { argb: "FF16213D" },
          };
          cell.fill = {
            type: "pattern",
            pattern: "solid",
            fgColor: {
              argb: rowIndex % 2 ? "FFF8FAFC" : "FFFFFFFF",
            },
          };
          cell.border = {
            bottom: {
              style: "hair",
              color: { argb: "FFE5E7EB" },
            },
          };
          cell.alignment = {
            vertical: "top",
            wrapText: true,
          };
        });

        row += 1;
      });

      row += 2;
    };

    writeSectionTitle("Status SLA Pelanggan");
    writeTable(
      [
        "Pelanggan",
        "Kontrak",
        "SLA Level",
        "Target Ketersediaan",
        "Waktu Respon",
        "Waktu Penyelesaian",
        "Status",
      ],
      filteredSlaRows.map(item => [
        item.customer,
        item.contractNumber,
        item.level,
        item.availabilityTarget,
        item.responseTime,
        item.resolutionTime,
        item.status,
      ])
    );

    writeSectionTitle("SLA Monitoring / Ticket Countdown");
    writeTable(
      [
        "Ticket",
        "Customer",
        "Priority",
        "Created",
        "Response Due",
        "Resolution Due",
        "Remaining Time",
        "Status",
      ],
      TICKETS.map(item => [
        item.ticket,
        item.customer,
        item.priority,
        item.created,
        item.responseDue,
        item.resolutionDue,
        item.remaining,
        item.status,
      ])
    );

    writeSectionTitle("Riwayat Eskalasi");
    writeTable(
      ["Tahap", "Status", "Waktu"],
      ESCALATION_STEPS.map(item => [item.role, item.status, item.time])
    );

    writeSectionTitle("Pelanggaran SLA & Service Credit");
    writeTable(
      [
        "Downtime",
        "Target Availability",
        "Actual Availability",
        "Status",
        "Service Credit",
      ],
      [["54 menit", "99.5%", "99.42%", "Miss", "5% dari biaya bulanan"]]
    );

    ws.getColumn(1).width = 25;
    ws.getColumn(2).width = 21;
    ws.getColumn(3).width = 16;
    ws.getColumn(4).width = 20;
    ws.getColumn(5).width = 20;
    ws.getColumn(6).width = 22;
    ws.getColumn(7).width = 18;
    ws.getColumn(8).width = 18;

    ws.views = [{ state: "frozen", ySplit: 6, showGridLines: false }];
    ws.headerFooter.oddFooter =
      "&LMSDC Surabaya - JTV&CSLA Monitoring&RPage &P / &N";

    const buffer = await workbook.xlsx.writeBuffer();

    downloadBlob(
      new Blob([buffer as unknown as BlobPart], {
        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      }),
      `msdc-sla-monitoring-${exportedAt.toISOString().slice(0, 10)}.xlsx`
    );
  }

